int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<int> a(n);
    unordered_map<int, int> total;
    for (auto &x : a) { scanf("%d", &x); total[x]++; }
    int limit = INT_MAX;
    for (auto &kv : total) limit = min(limit, kv.second);
    // Longest window in which every player appears at most `limit` times.
    unordered_map<int, int> counts;
    int left = 0, answer = 0;
    for (int right = 0; right < n; right++) {
        int v = a[right];
        counts[v]++;
        while (counts[v] > limit) { counts[a[left]]--; left++; }
        answer = max(answer, right - left + 1);
    }
    printf("%d\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken();
        int n = (int) st.nval;
        int[] a = new int[n];
        HashMap<Integer, Integer> total = new HashMap<>();
        for (int i = 0; i < n; i++) {
            st.nextToken();
            a[i] = (int) st.nval;
            total.merge(a[i], 1, Integer::sum);
        }
        int limit = Integer.MAX_VALUE;
        for (int c : total.values()) limit = Math.min(limit, c);
        // Longest window in which every player appears at most `limit` times.
        HashMap<Integer, Integer> counts = new HashMap<>();
        int left = 0, answer = 0;
        for (int right = 0; right < n; right++) {
            int v = a[right];
            counts.merge(v, 1, Integer::sum);
            while (counts.get(v) > limit) {
                counts.merge(a[left], -1, Integer::sum);
                left++;
            }
            answer = Math.max(answer, right - left + 1);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	total := map[int]int{}
	for i := range a {
		a[i] = nextInt()
		total[a[i]]++
	}
	limit := n
	for _, c := range total {
		limit = min(limit, c)
	}
	// Longest window in which every player appears at most `limit` times.
	counts := map[int]int{}
	left, answer := 0, 0
	for right, v := range a {
		counts[v]++
		for counts[v] > limit {
			counts[a[left]]--
			left++
		}
		answer = max(answer, right-left+1)
	}
	fmt.Println(answer)
}
